const MemeGenerator: React.FC = () => {
  const [prompt, setPrompt] = useState("");
  const [generating, setGenerating] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [logoBase64, setLogoBase64] = useState<string | null>(null);

  useEffect(() => {
    const fetchLogo = async () => {
      try {
        const response = await fetch(LOGO_URL);
        const blob = await response.blob();
        const reader = new FileReader();
        reader.onloadend = () => {
          const base64 = (reader.result as string).split(',')[1];
          setLogoBase64(base64);
        };
        reader.readAsDataURL(blob);
      } catch (err) {
        console.error("Failed to load logo for generator", err);
      }
    };
    fetchLogo();
  }, []);

  const randomPrompts = [
    "Skiing down a mountain of yellow snow",
    "Stuck inside a giant yellow snowball",
    "Ice fishing and catching a golden $TESTICLE coin",
    "Building a snowman that looks like a giant yellow ball",
    "Sledding on a golden coin through a blizzard",
    "Wearing a tiny yellow winter hat and scarf",
    "Eating a yellow popsicle in a snowstorm",
    "Ice skating on a vertical chart",
    "Fighting a blizzard with a yellow stick",
    "Waiting for the bus in a heavy yellow snowfall"
  ];

  const generateMeme = async (overridePrompt?: string) => {
    const activePrompt = overridePrompt || prompt;
    if (!activePrompt.trim()) return;

    setGenerating(true);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const contents = {
        parts: [
          ...(logoBase64 ? [{
            inlineData: {
              data: logoBase64,
              mimeType: 'image/jpeg',
            },
          }] : []),
          {
            text: `Generate a funny meme image. 
            STRICT RULES:
            1. BACKGROUND: Pure pitch black (#000000).
            2. CHARACTER HEAD: Must exactly match the provided logo image (a simple white/hand-drawn circle head).
            3. CHARACTER BODY: A simple, hand-drawn yellow stick-figure body (arms, legs, torso).
            4. STYLE: Hand-drawn, minimalist, 2D, funny meme aesthetic.
            5. SCENE: ${activePrompt}.
            6. COLOR PALETTE: Primarily Black, White (head), and Yellow (body and elements).
            Keep it clean and winter-themed.`,
          },
        ],
      };

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents,
      });

      let foundImage = false;
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) {
          setResultImage(`data:image/png;base64,${part.inlineData.data}`);
          foundImage = true;
          break;
        }
      }
      if (!foundImage) setError("No image was returned. Try again.");
    } catch (err) {
      console.error(err);
      setError("Failed to generate meme. Try again!");
    } finally {
      setGenerating(false);
    }
  };

  const handleRandomMeme = () => {
    const random = randomPrompts[Math.floor(Math.random() * randomPrompts.length)];
    setPrompt(random);
    generateMeme(random);
  };

  return (
    <section id="generator" className="py-24 px-6 bg-black relative">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-5xl md:text-6xl text-yellow-400 mb-4 text-center yellow-glow uppercase">Winter Meme Lab</h2>
        <p className="text-center text-xl mb-12 opacity-80 uppercase tracking-widest">Yellow stick-men only. Black backgrounds only.</p>

        <div className="bg-yellow-900/10 border-4 border-yellow-400 rounded-3xl p-6 md:p-10 shadow-[10px_10px_0px_rgba(251,191,36,0.2)]">
          <div className="flex flex-col gap-6">
            <div className="relative">
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Describe your winter meme idea..."
                className="w-full bg-black border-2 border-yellow-400/50 rounded-xl p-6 text-xl text-yellow-100 placeholder:text-yellow-400/30 focus:border-yellow-400 outline-none transition-all resize-none h-32"
              />
              <button 
                onClick={() => setPrompt(randomPrompts[Math.floor(Math.random() * randomPrompts.length)])}
                className="absolute right-4 bottom-4 text-yellow-400 hover:text-white transition-colors p-2"
                title="Shuffle Prompt"
              >
                <RefreshCw size={24} />
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <button
                onClick={() => generateMeme()}
                disabled={generating || !prompt.trim()}
                className="bg-yellow-400 text-black font-black text-2xl py-5 rounded-xl flex items-center justify-center gap-3 hover:bg-yellow-300 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-[6px_6px_0px_#78350f]"
              >
                {generating ? <Loader2 className="animate-spin" size={28} /> : <Wand2 size={28} />}
                COOK THE MEME
              </button>

              <button
                onClick={handleRandomMeme}
                disabled={generating}
                className="bg-black text-yellow-400 border-4 border-yellow-400 font-black text-2xl py-5 rounded-xl flex items-center justify-center gap-3 hover:bg-yellow-400 hover:text-black transition-all disabled:opacity-50 shadow-[6px_6px_0px_rgba(251,191,36,0.2)]"
              >
                <Sparkles size={28} />
                RANDOM MEME
              </button>
            </div>

            {error && <p className="text-red-500 text-center font-bold text-lg">{error}</p>}

            {resultImage && (
              <div className="mt-8 animate-in fade-in zoom-in duration-500">
                <div className="relative group rounded-2xl overflow-hidden border-4 border-yellow-400 bg-black aspect-square max-w-md mx-auto shadow-[15px_15px_0px_rgba(251,191,36,0.1)]">
                  <img src={resultImage} alt="Generated Meme" className="w-full h-full object-cover" />
                  <a 
                    href={resultImage} 
                    download="testicle-meme.png"
                    className="absolute top-4 right-4 bg-yellow-400 text-black p-3 rounded-full opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
                  >
                    <Download size={24} />
                  </a>
                </div>
                <p className="text-center text-yellow-400/60 mt-4 text-lg uppercase tracking-tighter italic">Pure Black & Yellow Art</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </section>
  );
};

