const Terminal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'agent', content: string }[]>([
    { 
      role: 'agent', 
      content: "TESTICLE AGENT V4.6 ONLINE.\n\nReady for alpha or just some light roasting? Ask me anything." 
    }
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput("");
    const updatedMessages = [...messages, { role: 'user' as const, content: userMsg }];
    setMessages(updatedMessages);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const history = messages.filter(m => messages.indexOf(m) > 0).map(m => ({
        role: m.role === 'user' ? 'user' as const : 'model' as const,
        parts: [{ text: m.content }]
      }));

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: [...history, { role: 'user', parts: [{ text: userMsg }] }],
        config: {
          systemInstruction: "You are Testicle Agent, a sharp, witty, and slightly sarcastic crypto expert. \n\nRULES:\n1. For casual chat, reply with a SHORT, funny one-liner.\n2. Only give detailed analysis if asked complex technical crypto questions.\n3. Your persona is a high-IQ stick figure agent. Be helpful but edgy.",
          temperature: 0.8,
        }
      });

      const agentText = response.text || "Handshake failed. Try again.";
      setMessages(prev => [...prev, { role: 'agent', content: agentText }]);
    } catch (err) {
      console.error("Terminal Error:", err);
      setMessages(prev => [...prev, { role: 'agent', content: "ERROR: Critical signal noise. Check API key or connection." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <motion.div 
      initial={{ opacity: 0, scale: 0.9, y: 20 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.9, y: 20 }}
      className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-10 pointer-events-none"
    >
      <div className="w-full max-w-2xl h-[550px] bg-[#050505] border-2 border-yellow-400 rounded-lg shadow-[0_0_40px_rgba(251,191,36,0.2)] flex flex-col overflow-hidden pointer-events-auto font-mono">
        {/* Header */}
        <div className="bg-yellow-400 text-black px-4 py-2 flex items-center justify-between font-bold">
          <div className="flex items-center gap-2">
            <TerminalIcon size={18} />
            <span>TESTICLE_TERMINAL_v4.6.exe</span>
          </div>
          <div className="flex items-center gap-3">
            <Minus size={18} className="cursor-pointer hover:opacity-70" />
            <Square size={14} className="cursor-pointer hover:opacity-70" />
            <X size={20} className="cursor-pointer hover:opacity-70" onClick={onClose} />
          </div>
        </div>

        {/* Content */}
        <div 
          ref={scrollRef}
          className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth bg-[radial-gradient(circle_at_center,_#111_0%,_#000_100%)]"
        >
          {messages.map((m, i) => (
            <div key={i} className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`max-w-[85%] p-3 rounded-lg ${m.role === 'user' ? 'bg-yellow-400 text-black shadow-[4px_4px_0_#451a03]' : 'bg-black/80 border border-yellow-400/30 text-yellow-400'}`}>
                <div className="text-[10px] opacity-60 mb-1 uppercase tracking-widest font-black">
                  {m.role === 'user' ? 'ROOT@SOLANA' : 'TESTICLE@AGENT'}
                </div>
                <div className="text-sm whitespace-pre-wrap leading-relaxed">
                  {m.content}
                </div>
              </div>
            </div>
          ))}
          {isLoading && (
            <div className="flex items-start">
              <div className="text-yellow-400/50 text-xs animate-pulse font-bold tracking-widest uppercase">
                Incoming Signal...
              </div>
            </div>
          )}
        </div>

        {/* Input */}
        <div className="p-4 bg-black border-t border-yellow-400/20">
          <div className="relative flex items-center gap-2">
            <span className="text-yellow-400 font-bold">$</span>
            <input 
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Hi, or ask for serious alpha..."
              className="flex-1 bg-transparent text-yellow-400 border-none outline-none placeholder:text-yellow-400/20 text-sm"
              autoFocus
            />
            <button 
              onClick={handleSend}
              className="text-yellow-400 hover:text-white transition-colors"
            >
              <Send size={18} />
            </button>
          </div>
        </div>
      </div>
    </motion.div>
  );
