    if (!activePrompt.trim()) return;

    setGenerating(true);
    setError(null);

    try {
      // Re-initialize inside the function to get the latest key
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Sanitize prompt for safety filters. Avoid triggering "testicle" filter.
      const sanitizedPrompt = activePrompt.replace(/testicle/gi, "stick character");

      const response = await ai.models.generateContent({
        model: apiKeySelected ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image',
        contents: {
          parts: [
            {
              text: `Generate a funny minimalist 2D meme image. 
