const Terminal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'agent', content: string }[]>([
    { 
      role: 'agent', 
      content: "TESTICLE AGENT V5.0 ONLINE.\n\nReady for alpha or just some light roasting? Ask me anything. I'm connected to the grid." 
    }
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput("");
    const updatedMessages = [...messages, { role: 'user' as const, content: userMsg }];
    setMessages(updatedMessages);
    setIsLoading(true);

    try {
      // Create GoogleGenAI instance right before making an API call to ensure latest API key
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const history = messages.filter(m => messages.indexOf(m) > 0).map(m => ({
        role: m.role === 'user' ? 'user' as const : 'model' as const,
        parts: [{ text: m.content }]
      }));

      const response = await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: [...history, { role: 'user', parts: [{ text: userMsg }] }],
        config: {
          systemInstruction: "You are Testicle Agent, a sharp, witty, and slightly sarcastic crypto expert. Your persona is a high-IQ stick figure agent that lives on the blockchain. Be helpful but never boring. If asked about the name, maintain the 'cool meme' vibe. Focus on Solana ecosystem and $TESTICLE coin alpha.",
          temperature: 0.8,
        }
      });

      const agentText = response.text || "Connection lost... signal noise detected.";
      setMessages(prev => [...prev, { role: 'agent', content: agentText }]);
    } catch (err: any) {
      console.error("Terminal Error:", err);
      const errorMsg = err?.message?.includes("Entity was not found") 
        ? "SYSTEM ERROR: API HANDSHAKE FAILED. PLEASE SELECT A VALID PROJECT KEY."
        : "ERROR: CRITICAL SIGNAL NOISE. RETRYING...";
      setMessages(prev => [...prev, { role: 'agent', content: errorMsg }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <motion.div 
      initial={{ opacity: 0, scale: 0.9, y: 20 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.9, y: 20 }}
