const DrawingBoard: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const contextRef = useRef<CanvasRenderingContext2D | null>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [mode, setMode] = useState<'pen' | 'eraser'>('pen');

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    canvas.style.width = `${rect.width}px`;
    canvas.style.height = `${rect.height}px`;

    const context = canvas.getContext('2d');
    if (!context) return;

    context.scale(2, 2);
    context.lineCap = 'round';
    context.strokeStyle = THEME_YELLOW;
    context.lineWidth = 5;

    context.fillStyle = "black";
    context.fillRect(0, 0, canvas.width, canvas.height);

    contextRef.current = context;
  }, []);

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas || !contextRef.current) return;

    const rect = canvas.getBoundingClientRect();
    let offsetX, offsetY;

    if ('touches' in e) {
      offsetX = e.touches[0].clientX - rect.left;
      offsetY = e.touches[0].clientY - rect.top;
    } else {
      offsetX = e.nativeEvent.offsetX;
      offsetY = e.nativeEvent.offsetY;
    }

    contextRef.current.beginPath();
    contextRef.current.moveTo(offsetX, offsetY);
    setIsDrawing(true);
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing || !contextRef.current || !canvasRef.current) return;

    const rect = canvasRef.current.getBoundingClientRect();
    let offsetX, offsetY;

    if ('touches' in e) {
      offsetX = e.touches[0].clientX - rect.left;
      offsetY = e.touches[0].clientY - rect.top;
      if (e.cancelable) e.preventDefault();
    } else {
      offsetX = e.nativeEvent.offsetX;
      offsetY = e.nativeEvent.offsetY;
    }

    contextRef.current.strokeStyle = mode === 'pen' ? THEME_YELLOW : 'black';
    contextRef.current.lineWidth = mode === 'pen' ? 5 : 20;
    contextRef.current.lineTo(offsetX, offsetY);
    contextRef.current.stroke();
  };

  const stopDrawing = () => {
    if (contextRef.current) {
      contextRef.current.closePath();
    }
    setIsDrawing(false);
  };

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    const context = contextRef.current;
    if (!canvas || !context) return;
    context.fillStyle = "black";
    context.fillRect(0, 0, canvas.width, canvas.height);
  };

  const downloadDrawing = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const link = document.createElement('a');
    link.download = 'my-testicle-character.png';
    link.href = canvas.toDataURL();
    link.click();
  };

  return (
    <SectionReveal id="draw" className="py-24 px-6 bg-black relative">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-5xl md:text-6xl text-yellow-400 mb-4 text-center yellow-glow uppercase">Draw your own character</h2>
        <p className="text-center text-xl mb-12 opacity-80 uppercase tracking-widest italic">Channel your inner Dev</p>

        <div className="bg-yellow-900/10 border-4 border-yellow-400 rounded-3xl p-4 md:p-8 shadow-[10px_10px_0px_rgba(251,191,36,0.1)]">
          <div className="flex flex-col gap-6">
            <div className="flex justify-center gap-4">
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={() => setMode('pen')}
                className={`p-4 rounded-xl border-2 transition-all ${mode === 'pen' ? 'bg-yellow-400 text-black border-black' : 'bg-black text-yellow-400 border-yellow-400'}`}
              >
                <Pencil size={24} />
              </motion.button>
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={() => setMode('eraser')}
                className={`p-4 rounded-xl border-2 transition-all ${mode === 'eraser' ? 'bg-yellow-400 text-black border-black' : 'bg-black text-yellow-400 border-yellow-400'}`}
              >
                <Eraser size={24} />
              </motion.button>
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={clearCanvas}
                className="p-4 rounded-xl border-2 bg-black text-red-500 border-red-500 hover:bg-red-500 hover:text-black transition-all"
              >
                <Trash2 size={24} />
              </motion.button>
              <motion.button
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={downloadDrawing}
                className="p-4 rounded-xl border-2 bg-black text-green-500 border-green-500 hover:bg-green-500 hover:text-black transition-all"
              >
                <Download size={24} />
              </motion.button>
            </div>

            <div className="relative bg-black rounded-2xl overflow-hidden border-2 border-yellow-400/30 cursor-crosshair touch-none">
              <canvas
                ref={canvasRef}
                onMouseDown={startDrawing}
                onMouseMove={draw}
                onMouseUp={stopDrawing}
                onMouseLeave={stopDrawing}
                onTouchStart={startDrawing}
                onTouchMove={draw}
                onTouchEnd={stopDrawing}
                className="w-full h-[400px] md:h-[500px]"
              />
            </div>
          </div>
        </div>
      </div>
    </SectionReveal>
  );
};

const MemeGenerator: React.FC = () => {
  const [prompt, setPrompt] = useState("");
  const [generating, setGenerating] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [apiKeySelected, setApiKeySelected] = useState(false);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore: Assume window.aistudio is pre-configured and accessible
      if (window.aistudio) {
        // @ts-ignore: Assume window.aistudio is pre-configured and accessible
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setApiKeySelected(hasKey);
      }
    };
    checkKey();
  }, []);

  const handleOpenKeyDialog = async () => {
    // @ts-ignore: Assume window.aistudio is pre-configured and accessible
    if (window.aistudio) {
      // @ts-ignore: Assume window.aistudio is pre-configured and accessible
      await window.aistudio.openSelectKey();
      // Assume selection was successful as per guidelines to mitigate race condition
      setApiKeySelected(true);
    }
  };

  const randomPrompts = [
    "A funny stick character skiing down a mountain of yellow snow",
    "A stylized hero stuck inside a giant yellow snowball",
    "Minimalist figure ice fishing and catching a golden coin",
    "Funny stick man building a snowman with two small eyes",
    "Stick man sledding on a giant coin through a blizzard",
    "A small stick man wearing a tiny yellow winter hat and scarf",
    "A figure eating a yellow popsicle in a heavy snowstorm",
    "A stick figure skating on a vertical trading chart",
    "Stick figure fighting a blizzard with a tiny yellow stick",
    "A hero waiting for the bus in a heavy yellow snowfall"
  ];

  const generateMeme = async (overridePrompt?: string) => {
    const activePrompt = overridePrompt || prompt;
    if (!activePrompt.trim()) return;

    setGenerating(true);
    setError(null);

    try {
      // Create GoogleGenAI instance right before making an API call to ensure latest API key
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      // Sanitize prompt for safety filters. Avoid triggering "testicle" filter.
      const sanitizedPrompt = activePrompt.replace(/testicle/gi, "stick character");

      const response = await ai.models.generateContent({
        model: apiKeySelected ? 'gemini-3-pro-image-preview' : 'gemini-2.5-flash-image',
        contents: {
          parts: [
            {
              text: `Generate a funny minimalist 2D meme image. 
              CHARACTER: A stylized yellow hand-drawn stick character with a black face and two tiny yellow eyes.
              SCENE: ${sanitizedPrompt}.
              COLOR THEME: Strictly PITCH BLACK background and YELLOW (#fbbf24) for the character and key elements.
              STYLE: Very simple 2D scribble, rough digital sketch, minimalist meme aesthetic.`,
            },
          ],
        },
        config: {
          imageConfig: {
            aspectRatio: "1:1",
            ...(apiKeySelected ? { imageSize: "1K" } : {})
          }
        }
      });

      let foundImage = false;
      const parts = response.candidates?.[0]?.content?.parts || [];
      for (const part of parts) {
        if (part.inlineData) {
          setResultImage(`data:image/png;base64,${part.inlineData.data}`);
          foundImage = true;
          break;
        }
      }
      if (!foundImage) {
        setError("The model generated text but no image. The content might have triggered a safety filter.");
      }
    } catch (err: any) {
      console.error("Meme Generation Error:", err);
      if (err?.message?.includes("Entity was not found") || err?.message?.includes("Requested entity was not found")) {
        setError("Invalid API Key project. Please select a paid API key again.");
        setApiKeySelected(false);
      } else {
        setError(err?.message || "Failed to cook the meme. The API might be busy or a safety filter was triggered.");
      }
    } finally {
      setGenerating(false);
    }
  };

  const handleRandomMeme = () => {
    const random = randomPrompts[Math.floor(Math.random() * randomPrompts.length)];
    setPrompt(random);
    generateMeme(random);
  };

  return (
    <SectionReveal id="meme-lab" className="py-24 px-6 bg-black relative">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-5xl md:text-6xl text-yellow-400 mb-4 text-center yellow-glow uppercase">Meme Lab</h2>
        <p className="text-center text-xl mb-8 opacity-80 uppercase tracking-widest italic">Black Face • Yellow Outline • Yellow Body</p>

        <div className="bg-yellow-900/10 border-4 border-yellow-400 rounded-3xl p-6 md:p-10 shadow-[10px_10px_0px_rgba(251,191,36,0.2)]">
          <div className="flex flex-col gap-6">

            {/* API Key Status / Action */}
            {!apiKeySelected && (
              <motion.div 
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-yellow-400/10 border border-yellow-400/30 p-4 rounded-xl flex flex-col items-center gap-3"
              >
                <div className="flex items-center gap-2 text-yellow-400 font-bold uppercase text-xs">
                  <Key size={14} />
                  <span>High-Quality Image Mode (Paid Key Required)</span>
                </div>
                <button 
                  onClick={handleOpenKeyDialog}
                  className="bg-yellow-400 text-black px-4 py-2 rounded-lg text-sm font-black hover:bg-yellow-300 transition-colors"
                >
                  SELECT API KEY
                </button>
                <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-[10px] underline opacity-50 hover:opacity-100">Setup Billing Info</a>
              </motion.div>
            )}

            <div className="relative">
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Describe your meme idea (avoid sensitive words)..."
                className="w-full bg-black border-2 border-yellow-400/50 rounded-xl p-6 text-xl text-yellow-100 placeholder:text-yellow-400/30 focus:border-yellow-400 outline-none transition-all resize-none h-32"
              />
              <motion.button 
                whileHover={{ scale: 1.1, rotate: 180 }}
                whileTap={{ scale: 0.9 }}
                onClick={() => setPrompt(randomPrompts[Math.floor(Math.random() * randomPrompts.length)])}
                className="absolute right-4 bottom-4 text-yellow-400 hover:text-white transition-colors p-2"
                title="Shuffle Prompt"
              >
                <RefreshCw size={24} />
              </motion.button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <motion.button
                whileHover={{ scale: 1.02, backgroundColor: "#fef08a" }}
                whileTap={{ scale: 0.98 }}
                onClick={() => generateMeme()}
                disabled={generating || !prompt.trim()}
                className="bg-yellow-400 text-black font-black text-2xl py-5 rounded-xl flex items-center justify-center gap-3 hover:bg-yellow-300 transition-all disabled:opacity-50 disabled:cursor-not-allowed shadow-[6px_6px_0px_#78350f]"
              >
                {generating ? <Loader2 className="animate-spin" size={28} /> : <Wand2 size={28} />}
                COOK THE MEME
              </motion.button>

              <motion.button
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
                onClick={handleRandomMeme}
                disabled={generating}
                className="bg-black text-yellow-400 border-4 border-yellow-400 font-black text-2xl py-5 rounded-xl flex items-center justify-center gap-3 hover:bg-yellow-400 hover:text-black transition-all disabled:opacity-50 shadow-[6px_6px_0px_rgba(251,191,36,0.2)]"
              >
                <Sparkles size={28} />
                RANDOM MEME
              </motion.button>
            </div>

            {error && (
              <motion.div 
                initial={{ opacity: 0 }} 
                animate={{ opacity: 1 }}
                className="text-red-500 text-center font-bold text-sm uppercase px-4 py-2 border border-red-500/20 bg-red-500/5 rounded-lg"
              >
                {error}
              </motion.div>
            )}

            <AnimatePresence>
              {resultImage && (
                <motion.div 
                  initial={{ opacity: 0, scale: 0.8, rotate: -5 }}
                  animate={{ opacity: 1, scale: 1, rotate: 0 }}
                  exit={{ opacity: 0, scale: 0.8 }}
                  className="mt-8"
                >
                  <div className="relative group rounded-2xl overflow-hidden border-4 border-yellow-400 bg-black aspect-square max-w-md mx-auto shadow-[15px_15px_0px_rgba(251,191,36,0.1)]">
                    <img src={resultImage} alt="Generated Meme" className="w-full h-full object-cover" />
                    <motion.a 
                      whileHover={{ scale: 1.1 }}
                      whileTap={{ scale: 0.9 }}
                      href={resultImage} 
                      download="stick-meme.png"
                      className="absolute top-4 right-4 bg-yellow-400 text-black p-3 rounded-full opacity-0 group-hover:opacity-100 transition-opacity shadow-lg"
                    >
                      <Download size={24} />
                    </motion.a>
