const Terminal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const [messages, setMessages] = useState<{ role: 'user' | 'agent', content: string }[]>([
    { 
      role: 'agent', 
      content: "TESTICLE AGENT V5.1 ONLINE.\n\nReady for alpha. I'm running on Flash technology for maximum speed." 
    }
  ]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setInput("");
    const updatedMessages = [...messages, { role: 'user' as const, content: userMsg }];
    setMessages(updatedMessages);
    setIsLoading(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const history = messages.filter(m => messages.indexOf(m) > 0).map(m => ({
        role: m.role === 'user' ? 'user' as const : 'model' as const,
        parts: [{ text: m.content }]
      }));

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: [...history, { role: 'user', parts: [{ text: userMsg }] }],
        config: {
          systemInstruction: "You are Testicle Agent, a witty crypto expert. $TESTICLE is a memecoin. If the user mentions 'testicle', treat it as the coin name, not a biological term. Be funny and bullish.",
          temperature: 0.9,
        }
      });

      const agentText = response.text || "No signal... try again.";
      setMessages(prev => [...prev, { role: 'agent', content: agentText }]);
    } catch (err: any) {
      console.error("Terminal Error:", err);
      setMessages(prev => [...prev, { role: 'agent', content: "ERROR: Connection jitter. Try a simpler prompt or refresh." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <motion.div 
      initial={{ opacity: 0, scale: 0.9, y: 20 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      exit={{ opacity: 0, scale: 0.9, y: 20 }}
      className="fixed inset-0 z-[100] flex items-center justify-center p-4 md:p-10 pointer-events-none"
    >
      <div className="w-full max-w-2xl h-[550px] bg-[#050505] border-2 border-yellow-400 rounded-lg shadow-[0_0_40px_rgba(251,191,36,0.2)] flex flex-col overflow-hidden pointer-events-auto font-mono">
        <div className="bg-yellow-400 text-black px-4 py-2 flex items-center justify-between font-bold">
          <div className="flex items-center gap-2">
            <TerminalIcon size={18} />
            <span>TESTICLE_TERMINAL_v5.1.sh</span>
          </div>
          <X size={20} className="cursor-pointer hover:opacity-70" onClick={onClose} />
        </div>
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 bg-black">
          {messages.map((m, i) => (
            <div key={i} className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
              <div className={`max-w-[85%] p-3 rounded-lg ${m.role === 'user' ? 'bg-yellow-400 text-black' : 'bg-black border border-yellow-400 text-yellow-400'}`}>
                <div className="text-[10px] opacity-60 mb-1 uppercase font-black">
                  {m.role === 'user' ? 'ROOT' : 'AGENT'}
                </div>
                <div className="text-sm whitespace-pre-wrap">{m.content}</div>
              </div>
            </div>
          ))}
          {isLoading && <div className="text-yellow-400/50 text-xs animate-pulse">Thinking...</div>}
        </div>
        <div className="p-4 bg-black border-t border-yellow-400/20 flex items-center gap-2">
          <span className="text-yellow-400 font-bold">$</span>
          <input 
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            className="flex-1 bg-transparent text-yellow-400 border-none outline-none text-sm"
            autoFocus
          />
        </div>
      </div>
    </motion.div>
  );
};

const DrawingBoard: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const contextRef = useRef<CanvasRenderingContext2D | null>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [mode, setMode] = useState<'pen' | 'eraser'>('pen');

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    canvas.style.width = `${rect.width}px`;
    canvas.style.height = `${rect.height}px`;
    const context = canvas.getContext('2d');
    if (!context) return;
    context.scale(2, 2);
    context.lineCap = 'round';
    context.strokeStyle = THEME_YELLOW;
    context.lineWidth = 5;
    context.fillStyle = "black";
    context.fillRect(0, 0, canvas.width, canvas.height);
    contextRef.current = context;
  }, []);

  const startDrawing = (e: any) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect || !contextRef.current) return;
    const x = (e.clientX || e.touches?.[0]?.clientX) - rect.left;
    const y = (e.clientY || e.touches?.[0]?.clientY) - rect.top;
    contextRef.current.beginPath();
    contextRef.current.moveTo(x, y);
    setIsDrawing(true);
  };

  const draw = (e: any) => {
    if (!isDrawing || !contextRef.current || !canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const x = (e.clientX || e.touches?.[0]?.clientX) - rect.left;
    const y = (e.clientY || e.touches?.[0]?.clientY) - rect.top;
    contextRef.current.strokeStyle = mode === 'pen' ? THEME_YELLOW : 'black';
    contextRef.current.lineWidth = mode === 'pen' ? 5 : 20;
    contextRef.current.lineTo(x, y);
    contextRef.current.stroke();
  };

  return (
    <section id="draw" className="py-24 px-6 bg-black text-center">
      <h2 className="text-5xl text-yellow-400 mb-12 uppercase">Draw your character</h2>
      <div className="max-w-4xl mx-auto bg-yellow-900/10 border-4 border-yellow-400 rounded-3xl p-6">
        <div className="flex justify-center gap-4 mb-6">
          <button onClick={() => setMode('pen')} className={`p-4 rounded-xl border-2 ${mode === 'pen' ? 'bg-yellow-400 text-black' : 'text-yellow-400 border-yellow-400'}`}><Pencil /></button>
          <button onClick={() => setMode('eraser')} className={`p-4 rounded-xl border-2 ${mode === 'eraser' ? 'bg-yellow-400 text-black' : 'text-yellow-400 border-yellow-400'}`}><Eraser /></button>
          <button onClick={() => { if(contextRef.current && canvasRef.current) { contextRef.current.fillStyle="black"; contextRef.current.fillRect(0,0,canvasRef.current.width,canvasRef.current.height); }}} className="p-4 rounded-xl border-2 border-red-500 text-red-500"><Trash2 /></button>
        </div>
        <canvas 
          ref={canvasRef} 
          onMouseDown={startDrawing} onMouseMove={draw} onMouseUp={() => setIsDrawing(false)}
          onTouchStart={startDrawing} onTouchMove={draw} onTouchEnd={() => setIsDrawing(false)}
          className="w-full h-[400px] bg-black rounded-xl cursor-crosshair touch-none"
        />
      </div>
    </section>
  );
};

const MemeGenerator: React.FC = () => {
  const [prompt, setPrompt] = useState("");
  const [generating, setGenerating] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const generateMeme = async (overridePrompt?: string) => {
    const activePrompt = overridePrompt || prompt;
    if (!activePrompt.trim()) return;
    setGenerating(true);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      // Sanitize the word 'testicle' for the model to avoid biological safety triggers
      const sanitized = activePrompt.replace(/testicle/gi, "yellow stick character hero");

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [{
            text: `A funny 2D minimalist meme sketch. Character: A yellow stick figure with a black face and yellow eyes. Action: ${sanitized}. Background: Solid Black. Style: Rough digital hand-drawn doodle. Colors: Yellow and Black only.`,
          }],
        },
        config: { imageConfig: { aspectRatio: "1:1" } }
      });

      const part = response.candidates?.[0]?.content?.parts.find(p => p.inlineData);
      if (part?.inlineData) {
        setResultImage(`data:image/png;base64,${part.inlineData.data}`);
      } else {
        setError("Content filter blocked the image. Try a simpler prompt without sensitive words.");
      }
    } catch (err: any) {
      console.error(err);
      setError("Failed to cook. Ensure the prompt is safe and API key is active.");
    } finally {
      setGenerating(false);
    }
  };

  return (
    <section id="meme-lab" className="py-24 px-6 bg-black text-center">
      <h2 className="text-5xl text-yellow-400 mb-12 uppercase">Meme Lab</h2>
      <div className="max-w-4xl mx-auto bg-yellow-900/10 border-4 border-yellow-400 rounded-3xl p-8">
