          >
            {generating ? <Loader2 className="animate-spin" /> : <Wand2 />} COOK MEME
          </button>
          <button 
            onClick={() => { const p = "Hero in a winter blizzard"; setPrompt(p); generateMeme(p); }}
            className="border-4 border-yellow-400 text-yellow-400 px-8 py-5 rounded-xl font-black text-2xl"
          >
            RANDOM
          </button>
        </div>
