          <div className="mt-8 relative group max-w-md mx-auto">
            <img src={resultImage} alt="Meme" className="w-full border-4 border-yellow-400 rounded-2xl" />
            <a href={resultImage} download="meme.png" className="absolute top-4 right-4 bg-yellow-400 p-2 rounded-full text-black opacity-0 group-hover:opacity-100 transition-opacity">
