const DrawingBoard: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const contextRef = useRef<CanvasRenderingContext2D | null>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [mode, setMode] = useState<'pen' | 'eraser'>('pen');

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    canvas.style.width = `${rect.width}px`;
    canvas.style.height = `${rect.height}px`;
    const context = canvas.getContext('2d');
    if (!context) return;
    context.scale(2, 2);
    context.lineCap = 'round';
    context.strokeStyle = THEME_YELLOW;
    context.lineWidth = 5;
    context.fillStyle = "black";
    context.fillRect(0, 0, canvas.width, canvas.height);
    contextRef.current = context;
  }, []);

  const startDrawing = (e: any) => {
    const rect = canvasRef.current?.getBoundingClientRect();
    if (!rect || !contextRef.current) return;
    const x = (e.clientX || e.touches?.[0]?.clientX) - rect.left;
    const y = (e.clientY || e.touches?.[0]?.clientY) - rect.top;
    contextRef.current.beginPath();
    contextRef.current.moveTo(x, y);
    setIsDrawing(true);
  };

  const draw = (e: any) => {
    if (!isDrawing || !contextRef.current || !canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const x = (e.clientX || e.touches?.[0]?.clientX) - rect.left;
    const y = (e.clientY || e.touches?.[0]?.clientY) - rect.top;
    contextRef.current.strokeStyle = mode === 'pen' ? THEME_YELLOW : 'black';
    contextRef.current.lineWidth = mode === 'pen' ? 5 : 20;
    contextRef.current.lineTo(x, y);
    contextRef.current.stroke();
  };

  return (
    <section id="draw" className="py-24 px-6 bg-black text-center">
      <h2 className="text-5xl md:text-6xl text-yellow-400 mb-12 uppercase yellow-glow">Draw your character</h2>
      <div className="max-w-4xl mx-auto bg-yellow-900/10 border-4 border-yellow-400 rounded-3xl p-6 shadow-[10px_10px_0_rgba(251,191,36,0.1)]">
        <div className="flex justify-center gap-4 mb-6">
          <button onClick={() => setMode('pen')} className={`p-4 rounded-xl border-2 transition-all ${mode === 'pen' ? 'bg-yellow-400 text-black border-black' : 'text-yellow-400 border-yellow-400'}`}><Pencil /></button>
          <button onClick={() => setMode('eraser')} className={`p-4 rounded-xl border-2 transition-all ${mode === 'eraser' ? 'bg-yellow-400 text-black border-black' : 'text-yellow-400 border-yellow-400'}`}><Eraser /></button>
          <button onClick={() => { if(contextRef.current && canvasRef.current) { contextRef.current.fillStyle="black"; contextRef.current.fillRect(0,0,canvasRef.current.width,canvasRef.current.height); }}} className="p-4 rounded-xl border-2 border-red-500 text-red-500 hover:bg-red-500 hover:text-black transition-all"><Trash2 /></button>
        </div>
        <canvas 
          ref={canvasRef} 
          onMouseDown={startDrawing} onMouseMove={draw} onMouseUp={() => setIsDrawing(false)}
          onTouchStart={startDrawing} onTouchMove={draw} onTouchEnd={() => setIsDrawing(false)}
          className="w-full h-[400px] bg-black rounded-xl cursor-crosshair touch-none border-2 border-yellow-400/20"
        />
      </div>
    </section>
  );
};

