    setGenerating(true);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      // Sanitize the prompt. If the model sees 'testicle' it might block. 
      // We'll describe the character visually instead to bypass the keyword filter while keeping the result.
      const visualPrompt = activePrompt.toLowerCase().includes('testicle') 
        ? activePrompt.replace(/testicle/gi, "stylized yellow stick figure character with a solid black face and two yellow dots for eyes")
        : activePrompt;

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
          parts: [{
            text: `A minimalist 2D digital meme illustration. 
