const DrawingBoard: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const contextRef = useRef<CanvasRenderingContext2D | null>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [mode, setMode] = useState<'pen' | 'eraser'>('pen');
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2; canvas.height = rect.height * 2;
    canvas.style.width = `${rect.width}px`; canvas.style.height = `${rect.height}px`;
    const context = canvas.getContext('2d');
    if (!context) return;
    context.scale(2, 2); context.lineCap = 'round'; context.strokeStyle = THEME_YELLOW; context.lineWidth = 5;
    context.fillStyle = "black"; context.fillRect(0, 0, canvas.width, canvas.height);
    contextRef.current = context;
  }, []);
  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current; if (!canvas || !contextRef.current) return;
    const rect = canvas.getBoundingClientRect();
    let offsetX, offsetY;
    if ('touches' in e) { offsetX = e.touches[0].clientX - rect.left; offsetY = e.touches[0].clientY - rect.top; }
    else { offsetX = e.nativeEvent.offsetX; offsetY = e.nativeEvent.offsetY; }
    contextRef.current.beginPath(); contextRef.current.moveTo(offsetX, offsetY); setIsDrawing(true);
  };
  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing || !contextRef.current || !canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    let offsetX, offsetY;
    if ('touches' in e) { offsetX = e.touches[0].clientX - rect.left; offsetY = e.touches[0].clientY - rect.top; if (e.cancelable) e.preventDefault(); }
    else { offsetX = e.nativeEvent.offsetX; offsetY = e.nativeEvent.offsetY; }
    contextRef.current.strokeStyle = mode === 'pen' ? THEME_YELLOW : 'black';
    contextRef.current.lineWidth = mode === 'pen' ? 5 : 20;
    contextRef.current.lineTo(offsetX, offsetY); contextRef.current.stroke();
  };
  const stopDrawing = () => { if (contextRef.current) contextRef.current.closePath(); setIsDrawing(false); };
  const clearCanvas = () => {
    const canvas = canvasRef.current; const context = contextRef.current; if (!canvas || !context) return;
    context.fillStyle = "black"; context.fillRect(0, 0, canvas.width, canvas.height);
  };
  const downloadDrawing = () => {
    const canvas = canvasRef.current; if (!canvas) return;
    const link = document.createElement('a'); link.download = 'my-testicle-character.png'; link.href = canvas.toDataURL(); link.click();
  };
  return (
    <SectionReveal id="draw" className="py-24 px-6 bg-black relative">
      <div className="max-w-4xl mx-auto">
        <h2 className="text-5xl md:text-6xl text-yellow-400 mb-4 text-center yellow-glow uppercase">Draw your own Testicle character</h2>
        <p className="text-center text-xl mb-12 opacity-80 uppercase tracking-widest italic">Channel your inner Dev</p>
        <div className="bg-yellow-900/10 border-4 border-yellow-400 rounded-3xl p-4 md:p-8 shadow-[10px_10px_0px_rgba(251,191,36,0.1)]">
          <div className="flex flex-col gap-6">
            <div className="flex justify-center gap-4">
              <button onClick={() => setMode('pen')} className={`p-4 rounded-xl border-2 transition-all ${mode === 'pen' ? 'bg-yellow-400 text-black border-black' : 'bg-black text-yellow-400 border-yellow-400'}`}><Pencil size={24} /></button>
              <button onClick={() => setMode('eraser')} className={`p-4 rounded-xl border-2 transition-all ${mode === 'eraser' ? 'bg-yellow-400 text-black border-black' : 'bg-black text-yellow-400 border-yellow-400'}`}><Eraser size={24} /></button>
              <button onClick={clearCanvas} className="p-4 rounded-xl border-2 bg-black text-red-500 border-red-500 hover:bg-red-500 hover:text-black transition-all"><Trash2 size={24} /></button>
              <button onClick={downloadDrawing} className="p-4 rounded-xl border-2 bg-black text-green-500 border-green-500 hover:bg-green-500 hover:text-black transition-all"><Download size={24} /></button>
            </div>
            <div className="relative bg-black rounded-2xl overflow-hidden border-2 border-yellow-400/30 cursor-crosshair touch-none">
              <canvas ref={canvasRef} onMouseDown={startDrawing} onMouseMove={draw} onMouseUp={stopDrawing} onMouseLeave={stopDrawing} onTouchStart={startDrawing} onTouchMove={draw} onTouchEnd={stopDrawing} className="w-full h-[400px] md:h-[500px]" />
            </div>
