  const [error, setError] = useState<string | null>(null);

  const randomPrompts = [
    "Yellow character skiing down a mountain of yellow snow",
    "Yellow character stuck inside a giant yellow snowball",
    "Yellow character ice fishing and catching a golden coin",
    "Yellow character building a snowman that looks exactly like him",
    "Yellow character sledding on a golden coin through a blizzard",
    "Yellow character wearing a tiny yellow winter hat and scarf",
    "Yellow character eating a yellow popsicle in a snowstorm",
    "Yellow character ice skating on a vertical trading chart",
    "Yellow character fighting a blizzard with a tiny yellow stick",
    "Yellow character waiting for the bus in a heavy yellow snowfall"
  ];

  const generateMeme = async (overridePrompt?: string) => {
    const activePrompt = overridePrompt || prompt;
    if (!activePrompt.trim() || generating) return;

    setGenerating(true);
    setError(null);

    try {
      // Use pollinations.ai to generate the image
      // We append visual style instructions to the prompt to keep it in theme
      const styleSuffix = ", minimalist 2D yellow and black scribble style, purely black background, thick yellow outlines, small yellow eyes, very simple hand-drawn meme aesthetic, high contrast black and yellow";
      const finalPrompt = activePrompt + styleSuffix;
      const seed = Math.floor(Math.random() * 1000000);
      const imageUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(finalPrompt)}?width=1024&height=1024&nologo=true&seed=${seed}`;

      // Pre-load the image to show the loader correctly
      const img = new Image();
      img.onload = () => {
        setResultImage(imageUrl);
        setGenerating(false);
      };
      img.onerror = () => {
        setError("Failed to fetch image from Pollinations. Try again.");
        setGenerating(false);
      };
      img.src = imageUrl;
    } catch (err) {
      console.error(err);
      setError("Failed to cook the meme. Try again!");
      setGenerating(false);
    }
  };

  const handleRandomMeme = () => {
    const random = randomPrompts[Math.floor(Math.random() * randomPrompts.length)];
    setPrompt(random);
    generateMeme(random);
  };

