    setError(null);

    try {
      /**
       * LOGO-PERFECT CHARACTER DNA:
       * We define the head as an "irregular potato-shaped wobbly ring".
       */
      const characterVisualIdentity = `
        The main character is 'Testicle'. 
        HEAD SPECIFICATION (MUST MATCH LOGO):
        1. SHAPE: The head is an irregular, bumpy, non-symmetrical potato-shaped ring. 
        2. OUTLINE: Thick, shaky, golden-yellow (#fbbf24) hand-drawn line.
        3. FACE: The area inside the yellow outline is PURE FLAT SOLID BLACK (#000000) void.
        4. EYES: Exactly two small, solid yellow blobs or dots (#fbbf24).
        5. EYE POSITION: Place the eyes UNEVENLY and ASYMMETRICALLY inside the black face. They should be slightly misaligned for a quirky look.
        6. NO FEATURES: No nose, no mouth, no shading.
        7. BODY: Simple primitive thin yellow stick-figure body.
      `;

      const scene = activePrompt;
      const aesthetic = "Masterpiece 2D digital doodle art, extremely high contrast, black and yellow color palette only. Solid black background. Rough felt-tip pen texture.";

      const finalPromptText = `Scene: ${scene}. Character: ${characterVisualIdentity}. Style: ${aesthetic}. Technical: clean lines, masterpiece quality.`;

      /**
       * HUGGING FACE INFERENCE API INTEGRATION
       * Using black-forest-labs/FLUX.1-dev for highest instruction following.
       * If HF_TOKEN is missing, we fallback to Pollinations for functionality.
       */
      let imageUrl = "";

      if (HF_TOKEN) {
        const response = await fetch(
          "https://api-inference.huggingface.co/models/black-forest-labs/FLUX.1-dev",
          {
            headers: { Authorization: `Bearer ${HF_TOKEN}`, "Content-Type": "application/json" },
            method: "POST",
            body: JSON.stringify({ inputs: finalPromptText }),
          }
        );

        if (!response.ok) throw new Error("Hugging Face API Error");

        const blob = await response.blob();
        imageUrl = URL.createObjectURL(blob);
      } else {
        // Fallback to Pollinations (which is free and doesn't require keys)
        const seed = Math.floor(Math.random() * 1000000);
        imageUrl = `https://image.pollinations.ai/prompt/${encodeURIComponent(finalPromptText)}?width=1024&height=1024&nologo=true&seed=${seed}&model=flux`;
      }

      const img = new Image();
      img.onload = () => {
        setResultImage(imageUrl);
        setGenerating(false);
      };
      img.onerror = () => {
        setError("AI Engine stalled. Check API connection.");
        setGenerating(false);
      };
      img.src = imageUrl;
    } catch (err) {
      console.error(err);
      setError("Failed to connect to Hugging Face. Ensure your HF_TOKEN is valid or try again.");
      setGenerating(false);
    }
  };

  const handleRandomMeme = () => {
    const random = randomPrompts[Math.floor(Math.random() * randomPrompts.length)];
    setPrompt(random);
    generateMeme(random);
  };

  return (
    <SectionReveal id="meme-lab" className="py-24 px-6 bg-black relative">
      <div className="max-w-4xl mx-auto">
        <div className="flex items-center justify-center gap-4 mb-8">
