        </div>
        <p className="text-center text-xl mb-12 opacity-80 uppercase tracking-widest italic font-bold">Powered by Hugging Face Inference</p>

        <div className="bg-yellow-900/10 border-4 border-yellow-400 rounded-3xl p-6 md:p-10 shadow-[15px_15px_0px_rgba(251,191,36,0.1)]">
          <div className="flex flex-col gap-6">
            <div className="relative">
              <textarea
                value={prompt}
                onChange={(e) => setPrompt(e.target.value)}
                placeholder="Where should Testicle go next? (e.g. Testicle in a yellow submarine...)"
                className="w-full bg-black border-2 border-yellow-400/30 rounded-xl p-6 text-xl text-yellow-100 placeholder:text-yellow-400/20 focus:border-yellow-400 outline-none transition-all resize-none h-32"
              />
              <motion.button 
                whileHover={{ scale: 1.1, rotate: 180 }}
                whileTap={{ scale: 0.9 }}
                onClick={() => setPrompt(randomPrompts[Math.floor(Math.random() * randomPrompts.length)])}
                className="absolute right-4 bottom-4 text-yellow-400 hover:text-white transition-colors p-2"
              >
                <RefreshCw size={24} />
              </motion.button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <motion.button
                whileHover={{ scale: 1.02, backgroundColor: "#fef08a" }}
                whileTap={{ scale: 0.98 }}
                onClick={() => generateMeme()}
                disabled={generating || !prompt.trim()}
                className="bg-yellow-400 text-black font-black text-2xl py-6 rounded-xl flex items-center justify-center gap-3 hover:bg-yellow-300 transition-all disabled:opacity-50 shadow-[6px_6px_0px_#78350f]"
              >
                {generating ? <Loader2 className="animate-spin" size={28} /> : <Zap size={28} />}
                COOK ON HF
              </motion.button>
              <motion.button
                whileHover={{ scale: 1.02 }}
                whileTap={{ scale: 0.98 }}
