                className="bg-black text-yellow-400 border-4 border-yellow-400 font-black text-2xl py-6 rounded-xl flex items-center justify-center gap-3 hover:bg-yellow-400 hover:text-black transition-all disabled:opacity-50"
              >
                <Sparkles size={28} />
                SURPRISE ME
              </motion.button>
            </div>

            {error && <p className="text-red-500 text-center font-bold text-lg uppercase bg-red-500/10 p-4 rounded-xl border border-red-500/30">{error}</p>}

            <AnimatePresence>
