const getEnvToken = (): string => {
  // Vite client-side exposed variables MUST have VITE_ prefix
  // @ts-ignore
  const viteToken = import.meta.env?.VITE_HF_TOKEN || import.meta.env?.VITE_API_KEY;
  if (viteToken) return viteToken;

  // Fallbacks for other environments
  const processToken = process.env.API_KEY || (process.env as any).HF_TOKEN || (process.env as any).VITE_HF_TOKEN;
  if (processToken) return processToken;

  return "";
};

