      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const logoData = await getLogoBase64();

      const contents: any[] = [];

      // If we could fetch the logo, send it as a reference
      if (logoData) {
        contents.push({
          inlineData: {
            mimeType: 'image/jpeg',
            data: logoData
