    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const logoData = await getLogoBase64();

      const contents: any[] = [];

      if (logoData) {
        contents.push({
          inlineData: {
            mimeType: 'image/jpeg',
            data: logoData
