const DrawingBoard: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const contextRef = useRef<CanvasRenderingContext2D | null>(null);
  const [isDrawing, setIsDrawing] = useState(false);
  const [mode, setMode] = useState<'pen' | 'eraser'>('pen');

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * 2;
    canvas.height = rect.height * 2;
    canvas.style.width = `${rect.width}px`;
    canvas.style.height = `${rect.height}px`;
    const context = canvas.getContext('2d');
    if (!context) return;
    context.scale(2, 2);
    context.lineCap = 'round';
    context.strokeStyle = THEME_YELLOW;
    context.lineWidth = 5;
    context.fillStyle = "black";
    context.fillRect(0, 0, canvas.width, canvas.height);
    contextRef.current = context;
  }, []);

  const getCoordinates = (e: React.MouseEvent | React.TouchEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    if ('touches' in e) {
      return {
        x: (e as React.TouchEvent).touches[0].clientX - rect.left,
        y: (e as React.TouchEvent).touches[0].clientY - rect.top
      };
    } else {
      return {
        x: (e as React.MouseEvent).nativeEvent.offsetX,
        y: (e as React.MouseEvent).nativeEvent.offsetY
      };
    }
  };

  const startDrawing = (e: React.MouseEvent | React.TouchEvent) => {
    if (!contextRef.current) return;
    const { x, y } = getCoordinates(e);
    contextRef.current.beginPath();
    contextRef.current.moveTo(x, y);
    setIsDrawing(true);
  };

  const draw = (e: React.MouseEvent | React.TouchEvent) => {
    if (!isDrawing || !contextRef.current) return;
    const { x, y } = getCoordinates(e);
    contextRef.current.strokeStyle = mode === 'pen' ? THEME_YELLOW : 'black';
    contextRef.current.lineWidth = mode === 'pen' ? 5 : 25;
    contextRef.current.lineTo(x, y);
    contextRef.current.stroke();
    if ('touches' in e && e.cancelable) e.preventDefault();
  };

  const stopDrawing = () => {
    if (contextRef.current) contextRef.current.closePath();
    setIsDrawing(false);
  };

  const clearCanvas = () => {
    const canvas = canvasRef.current;
    const context = contextRef.current;
    if (!canvas || !context) return;
    context.fillStyle = "black";
    context.fillRect(0, 0, canvas.width, canvas.height);
  };

  const downloadDrawing = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const link = document.createElement('a');
    link.download = 'my-doodle.png';
    link.href = canvas.toDataURL();
    link.click();
  };

  return (
    <SectionReveal id="draw" className="py-24 px-6 bg-black relative">
      <div className="max-w-7xl mx-auto">
        <h2 className="text-5xl md:text-6xl text-yellow-400 mb-4 text-center yellow-glow uppercase">Draw Something Crude</h2>
        <p className="text-center text-xl mb-12 opacity-80 uppercase tracking-widest italic">The $testicle way</p>

        <div className="flex flex-col md:flex-row gap-6 items-stretch">
          {/* Toolbar Sidebar */}
          <div className="w-full md:w-auto flex md:flex-col gap-4 justify-center md:justify-start bg-yellow-900/10 p-4 rounded-3xl border-2 border-yellow-400/30">
            <button onClick={() => setMode('pen')} title="Pen" className={`p-4 rounded-xl border-2 transition-all ${mode === 'pen' ? 'bg-yellow-400 text-black border-black shadow-[4px_4px_0_#000]' : 'bg-black text-yellow-400 border-yellow-400 hover:bg-yellow-400/20'}`}><Pencil size={28} /></button>
            <button onClick={() => setMode('eraser')} title="Eraser" className={`p-4 rounded-xl border-2 transition-all ${mode === 'eraser' ? 'bg-yellow-400 text-black border-black shadow-[4px_4px_0_#000]' : 'bg-black text-yellow-400 border-yellow-400 hover:bg-yellow-400/20'}`}><Eraser size={28} /></button>
            <div className="w-full h-0.5 bg-yellow-400/20 md:my-2 hidden md:block"></div>
            <button onClick={clearCanvas} title="Clear" className="p-4 rounded-xl border-2 bg-black text-red-500 border-red-500 hover:bg-red-500 hover:text-black transition-all hover:shadow-[4px_4px_0_#500]"><Trash2 size={28} /></button>
            <button onClick={downloadDrawing} title="Save" className="p-4 rounded-xl border-2 bg-black text-green-500 border-green-500 hover:bg-green-500 hover:text-black transition-all hover:shadow-[4px_4px_0_#050]"><Download size={28} /></button>
          </div>

          {/* Canvas Area */}
          <div className="flex-1 bg-yellow-400/5 border-4 border-yellow-400 rounded-3xl p-4 md:p-8 shadow-[12px_12px_0px_#451a03] relative overflow-hidden">
            <div className="relative bg-black rounded-2xl overflow-hidden border-2 border-yellow-400/30 cursor-crosshair touch-none h-full min-h-[400px]">
              <canvas
                ref={canvasRef}
                onMouseDown={startDrawing}
                onMouseMove={draw}
                onMouseUp={stopDrawing}
                onMouseLeave={stopDrawing}
                onTouchStart={startDrawing}
                onTouchMove={draw}
                onTouchEnd={stopDrawing}
                className="w-full h-full absolute inset-0"
              />
            </div>
          </div>
        </div>
      </div>
    </SectionReveal>
  );
};

const MemeGenerator: React.FC = () => {
  const [prompt, setPrompt] = useState("");
  const [memeText, setMemeText] = useState("");
  const [generating, setGenerating] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const randomScenarios = [
    "Testicle character chillin on a pile of gold coins",
    "Testicle character flying a yellow rocket to Mars",
    "Testicle character fighting a giant snowball",
    "Testicle character wearing a crown in a dark palace",
    "Testicle character surfing on a tidal wave of SOL",
    "Testicle character at the gym lifting 1000kg",
    "Testicle character as a yellow DJ in a club",
    "Testicle character meditating on top of a mountain"
  ];

  const handleRandom = () => {
    const scenario = randomScenarios[Math.floor(Math.random() * randomScenarios.length)];
    setPrompt(scenario);
    generateMeme(scenario);
  };

  const getLogoBase64 = async () => {
    try {
      const response = await fetch(LOGO_URL);
      const blob = await response.blob();
      return new Promise<string>((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
        reader.readAsDataURL(blob);
      });
    } catch (e) {
      return null;
    }
  };

  const generateMeme = async (overridePrompt?: string) => {
    const activePrompt = (overridePrompt || prompt).trim();
    if (!activePrompt || generating) return;

    setGenerating(true);
    setError(null);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const logoData = await getLogoBase64();

      const contents: any[] = [];

      if (logoData) {
        contents.push({
          inlineData: {
            mimeType: 'image/jpeg',
            data: logoData
          }
        });
      }

      const instruction = `
        STYLE: Crude primitive marker doodle, simple 2D sketch.
        COLORS: Strictly Pure Black and Golden Yellow (#fbbf24) ONLY.
        MANDATORY CHARACTER DESIGN: The character MUST have the EXACT SAME HEAD as shown in the provided logo image (the wobbly, slightly asymmetric testicle head with those specific eyes).
        BODY: Simple yellow stick figure body attached to that head.
        BACKGROUND: Absolute solid black.
        SCENE: ${activePrompt}.
        ${memeText ? `Include text "${memeText.toUpperCase()}" in hand-drawn messy yellow marker letters.` : ""}
        NO GRADIENTS. NO SHADING. ONLY FLAT YELLOW AND BLACK.
      `;

      contents.push({ text: instruction });

      const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: { parts: contents },
        config: { imageConfig: { aspectRatio: "1:1" } },
      });

      const part = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
      if (part?.inlineData) {
        setResultImage(`data:image/png;base64,${part.inlineData.data}`);
      } else {
        throw new Error("No image generated. Please check your API key and connection.");
      }
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Something went wrong. The API key might be invalid.");
    } finally {
      setGenerating(false);
    }
  };

  return (
    <SectionReveal id="meme-lab" className="py-24 px-6 bg-black relative">
      <div className="max-w-7xl mx-auto">
        <div className="text-center mb-16">
