            {/* Image Column - Now First/Left */}
            <div className="order-1 lg:order-1 relative aspect-square bg-black rounded-[2rem] border-2 border-dashed border-yellow-400/20 flex items-center justify-center overflow-hidden shadow-2xl h-full min-h-[300px]">
              <AnimatePresence mode="wait">
                {generating ? (
                  <motion.div key="loading" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="flex flex-col items-center gap-6">
                    <Loader2 size={80} className="text-yellow-400 animate-spin" />
                    <p className="text-yellow-400 font-black uppercase tracking-[0.2em] animate-pulse">Syncing with Logo Core...</p>
                  </motion.div>
                ) : resultImage ? (
