const MemeGenerator: React.FC = () => {
  const [caption, setCaption] = useState("");
  const [generating, setGenerating] = useState(false);
  const [resultImage, setResultImage] = useState<string | null>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const logoRef = useRef<HTMLImageElement | null>(null);

  useEffect(() => {
    // Preload logo for canvas operations
    const initLogo = async () => {
        try {
            const res = await fetch(LOGO_URL);
            const blob = await res.blob();
            const img = new Image();
            img.src = URL.createObjectURL(blob);
            img.onload = () => { logoRef.current = img; };
        } catch (e) {
            console.error("Logo load failed", e);
            const img = new Image();
            img.crossOrigin = "anonymous";
            img.src = LOGO_URL;
            img.onload = () => { logoRef.current = img; };
        }
    };
    initLogo();
  }, []);

  const drawRoughLine = (ctx: CanvasRenderingContext2D, x1: number, y1: number, x2: number, y2: number) => {
    ctx.beginPath();
    const roughness = 2;
    const midX = (x1 + x2) / 2 + (Math.random() - 0.5) * 10 * roughness;
    const midY = (y1 + y2) / 2 + (Math.random() - 0.5) * 10 * roughness;
    ctx.moveTo(x1, y1);
    ctx.quadraticCurveTo(midX, midY, x2, y2);
    ctx.stroke();
  };

  const generateMeme = () => {
    if (!canvasRef.current || !logoRef.current || generating) return;
    setGenerating(true);

    // Simulate "processing" - procedural generation is fast but we want to show effect
    setTimeout(() => {
        const canvas = canvasRef.current!;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        const w = canvas.width;
        const h = canvas.height;

        // Background
        ctx.fillStyle = "#000000";
        ctx.fillRect(0, 0, w, h);

        // Styling
        ctx.strokeStyle = THEME_YELLOW;
        ctx.lineWidth = 8;
        ctx.lineCap = "round";
        ctx.lineJoin = "round";
        ctx.shadowColor = THEME_YELLOW;
        ctx.shadowBlur = 15;

        const cx = w / 2;

        // Procedural Body Generation
        const headY = 180;
        const headSize = 180;

        // 1. Torso
        const torsoLen = 120 + Math.random() * 40;
        const hipY = headY + torsoLen;
        drawRoughLine(ctx, cx, headY + 50, cx, hipY);

        // 2. Arms
        const shoulderY = headY + 70;
        const armLen = 100;
        // Left Arm (Random angles)
        const laAngle = Math.PI * 0.7 + (Math.random() * 0.5);
        const lax = cx + Math.cos(laAngle) * armLen;
        const lay = shoulderY + Math.sin(laAngle) * armLen;
        drawRoughLine(ctx, cx, shoulderY, lax, lay);
        // Right Arm
        const raAngle = Math.PI * 0.3 - (Math.random() * 0.5);
        const rax = cx + Math.cos(raAngle) * armLen;
        const ray = shoulderY + Math.sin(raAngle) * armLen;
        drawRoughLine(ctx, cx, shoulderY, rax, ray);

        // 3. Legs
        const legLen = 140;
        // Left Leg
        drawRoughLine(ctx, cx, hipY, cx - 60 - Math.random() * 40, hipY + legLen);
        // Right Leg
        drawRoughLine(ctx, cx, hipY, cx + 60 + Math.random() * 40, hipY + legLen);

        // Draw Head (Image)
        ctx.save();
        ctx.shadowBlur = 0;
        ctx.translate(cx, headY);
        ctx.rotate((Math.random() - 0.5) * 0.3);
        ctx.drawImage(logoRef.current!, -headSize/2, -headSize/2, headSize, headSize);
        ctx.restore();

        // Props/Decorations (Random)
        ctx.fillStyle = THEME_YELLOW;
        ctx.font = "bold 40px 'Permanent Marker'";
        for(let i=0; i<8; i++) {
            if (Math.random() > 0.6) {
                const px = Math.random() * w;
                const py = Math.random() * h;
                if (Math.abs(px - cx) > 100) {
                     ctx.fillText(Math.random() > 0.5 ? "★" : "$", px, py);
                }
            }
        }

        // Caption
        if (caption.trim()) {
            ctx.shadowBlur = 0;
            ctx.shadowColor = "transparent";
            ctx.font = "400 50px 'Permanent Marker'";
            ctx.textAlign = "center";
            ctx.textBaseline = "bottom";

            const text = caption.toUpperCase();
            const textX = w / 2;
            const textY = h - 40;

            // Stroke
            ctx.strokeStyle = "black";
            ctx.lineWidth = 8;
            ctx.strokeText(text, textX, textY);

            // Fill
            ctx.fillStyle = THEME_YELLOW;
            ctx.fillText(text, textX, textY);
        }

        setResultImage(canvas.toDataURL("image/png"));
        setGenerating(false);
    }, 600);
  };

  const downloadMeme = () => {
    if (resultImage) {
        const link = document.createElement('a');
        link.download = 'testicle-meme.png';
        link.href = resultImage;
        link.click();
    }
  };

  return (
    <SectionReveal id="sack-lab" className="py-16 md:py-24 px-4 md:px-6 bg-black relative">
      <div className="max-w-5xl mx-auto">
        <div className="text-center mb-10 md:mb-16">
          <Rocket size={40} className="mx-auto mb-4 md:mb-6 text-yellow-400 animate-bounce" />
          <h2 className="text-5xl md:text-7xl text-yellow-400 mb-2 md:mb-4 yellow-glow uppercase">Sack-Lab</h2>
          <p className="text-lg md:text-xl opacity-60 uppercase tracking-widest italic">Procedural Sack-Generator</p>
        </div>
        <div className="bg-black border-4 border-yellow-400 rounded-2xl md:rounded-[2.5rem] p-6 md:p-12">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 md:gap-12 items-center">

            <div className="space-y-6 order-2 lg:order-1">
              <div className="bg-yellow-400/10 p-6 rounded-xl border border-yellow-400/30">
                <p className="text-sm text-yellow-400/80 mb-2 uppercase font-bold tracking-wider">CAPTION THIS SACK:</p>
                <input 
                  type="text" 
                  value={caption} 
                  onChange={(e) => setCaption(e.target.value)} 
                  placeholder="TO THE MOON..." 
                  className="w-full bg-black border-2 border-yellow-400 rounded-xl p-4 text-yellow-400 text-xl md:text-2xl font-black outline-none focus:shadow-[0_0_20px_rgba(251,191,36,0.3)] transition-all placeholder:text-yellow-400/30" 
                />
              </div>

              <button 
                onClick={generateMeme} 
                disabled={generating} 
                className="w-full bg-yellow-400 text-black font-black text-2xl py-6 rounded-xl flex items-center justify-center gap-3 hover:bg-yellow-300 hover:scale-[1.02] active:scale-[0.98] transition-all shadow-[0_0_30px_rgba(251,191,36,0.4)]"
              >
                {generating ? <Loader2 className="animate-spin w-8 h-8" /> : <Zap className="w-8 h-8 fill-black" />} 
                {resultImage ? "RE-ROLL SACK" : "GENERATE SACK"}
              </button>

              {resultImage && (
                  <button onClick={downloadMeme} className="w-full bg-black border-2 border-yellow-400 text-yellow-400 font-bold text-lg py-4 rounded-xl flex items-center justify-center gap-2 hover:bg-yellow-400/10 transition-all">
                      <Download size={20} /> DOWNLOAD HD
                  </button>
              )}
            </div>

            <div className="order-1 lg:order-2 aspect-square bg-black rounded-2xl border-4 border-dashed border-yellow-400/30 flex items-center justify-center overflow-hidden relative group">
                <canvas ref={canvasRef} width={800} height={800} className="hidden" />
                {generating ? (
                    <div className="flex flex-col items-center gap-4">
                        <Loader2 size={80} className="text-yellow-400 animate-spin" />
                        <span className="text-yellow-400 animate-pulse font-black tracking-widest">BREWING...</span>
                    </div>
                ) : resultImage ? (
                    <img src={resultImage} alt="Meme" className="w-full h-full object-contain hover:scale-105 transition-transform duration-500" />
                ) : (
                    <div className="text-center opacity-30">
                        <Sparkles size={80} className="mx-auto mb-4" />
                        <span className="font-black text-2xl tracking-widest">READY TO COOK</span>
                    </div>
                )}
            </div>

          </div>
        </div>
      </div>
    </SectionReveal>
  );
};

