        try {
            const res = await fetch(LOGO_URL);
            const blob = await res.blob();
            const img = new Image();
            img.src = URL.createObjectURL(blob);
            img.onload = () => { logoRef.current = img; };
        } catch (e) {
            console.error("Logo load failed", e);
            const img = new Image();
            img.crossOrigin = "anonymous";
            img.src = LOGO_URL;
            img.onload = () => { logoRef.current = img; };
        }
    };
    initLogo();
  }, []);

  const generateMeme = async () => {
    if (!canvasRef.current || generating) return;
    setGenerating(true);

    try {
        const seed = Math.floor(Math.random() * 1000000);
        // Fallback prompt ensures generation always works with a subject
        const promptText = caption.trim() ? caption : "crazy crypto meme explosion";
        // Prompt engineering for specific style consistency
        const finalPrompt = `(masterpiece), best quality, simple yellow marker drawing on black background, ${promptText}, yellow #fbbf24, vector art, meme style, thick lines, minimalist, high contrast, dark void`;

        const response = await fetch(`https://image.pollinations.ai/prompt/${encodeURIComponent(finalPrompt)}?width=800&height=800&nologo=true&seed=${seed}&model=flux`);

        if (!response.ok) throw new Error("Generation failed");

        const blob = await response.blob();
        const img = await createImageBitmap(blob);

        const canvas = canvasRef.current;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        // Reset canvas
        ctx.fillStyle = "black";
        ctx.fillRect(0, 0, canvas.width, canvas.height);

        // Draw generated image
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

        // Draw branding watermark
